"derived": [], "justification": "'any dividing space, barrier or section' is st.median_or_divider: 'physical barrier or dividing section between roadways'. 'driven over, across or within' it is the footprint overlapping it at the observation: rel.occupies ('a road user's footprint overlaps a lane / region (... median ...)'), which holds over, across and within alike."}, {"span": "s6", "atoms": ["st.median_or_divider", "rel.occupies"], "derived": [], "justification": "'an opening in the barrier or dividing section or space' is the st.median_or_divider region carrying its 'opening attribute where a crossover exists'; 'through' it is the footprint overlapping that opening region (rel.occupies)."}, {"span": "s7", "atoms": ["st.median_or_divider", "st.intersection", "rel.occupies"], "derived": [], "justification": "'a crossover' is the divider's opening (st.median_or_divider: 'opening attribute where a crossover exists'); 'intersection' (DEF-NRS-484A-105; on a divided highway 'every crossing of each roadway ... shall be regarded as a separate intersection') is st.intersection: 'the region where two roadways meet', 'not a stand-in for a crosswalk or a stop line', neither of which is read. 'at' is the footprint overlapping the opening or the intersection (rel.occupies). 'established by a public authority' is read through the feature's presence (status reading)."}], "operationalizations": [], "assumptions": [], "intentions": [], "compositions": [], "residues": [], "binders": [{"name": "x", "class_elements": ["ru.aggregate=DEF-NRS-484A-320::vehicle"]}], "applicability": "x is a member of the vehicle aggregate and existsRegion st.highway h: rel.occupies(x, h) and existsRegion st.median_or_divider m: st.on_way(m, h).", "obligation": "forallRegion st.median_or_divider m: (rel.occupies(x, m) and st.on_way(m, h) for a highway h x occupies) implies (the opening attribute of m holds, or existsRegion st.intersection i: rel.occupies(x, i)).", "params": [], "narrowings": [{"span": "s2", "why": "'driven' is read through the vehicle's presence on the road: a vehicle on the road is taken to be driven.", "kind": "observable_reading", "category": "agency"}, {"span": "s7", "why": "'established by a public authority' (the legal status of the crossover or intersection) is read through the opening's or the intersection's presence on the road.", "kind": "observable_reading", "category": "status"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A car drives across a raised median section without an opening, between intersections: its footprint overlaps a st.median_or_divider region whose opening attribute is false, and no intersection."}, {"name": "permit", "expected": "compliant", "narrative": "A car moves along the right-hand roadway; its footprint overlaps no median or divider region."}, {"name": "idle", "expected": "not_applicable", "narrative": "A car on an undivided highway (no st.median_or_divider on it) crosses its painted centre line."}, {"name": "blind", "expected": "unknown", "narrative": "A car moves next to the median; rel.occupies is declared absent.", "masked": ["rel.occupies"]}, {"name": "branch_1", "expected": "compliant", "narrative": "A car crosses the median through a crossover: its footprint overlaps a median region whose opening attribute is true."}, {"name": "branch_2", "expected": "compliant", "narrative": "A car turning at an intersection of the divided highway clips the median nose: its footprint overlaps the median and the st.intersection region."}], "literals": [], "param_proposals": [], "gaps": []}
