", "why": "'driven' is read through the vehicle's presence on the road: a vehicle on the road is taken to be driven.", "kind": "observable_reading", "category": "agency"}, {"span": "s7", "why": "'established by a public authority' (the legal status of the crossover or intersection) is read through the opening's or the intersection's presence on the road.", "kind": "observable_reading", "category": "status"}], "scenarios": [{"name": "forbid", "expected": "violated", "narrative": "A car drives across a raised median section without an opening, between intersections: its footprint overlaps a st.median_or_divider region whose opening attribute is false, and no intersection."}, {"name": "permit", "expected": "compliant", "narrative": "A car moves along the right-hand roadway; its footprint overlaps no median or divider region."}, {"name": "idle", "expected": "not_applicable", "narrative": "A car on an undivided highway (no st.median_or_divider on it) crosses its painted centre line."}, {"name": "blind", "expected": "unknown", "narrative": "A car moves next to the median; rel.occupies is declared absent.", "masked": ["rel.occupies"]}, {"name": "branch_1", "expected": "compliant", "narrative": "A car crosses the median through a crossover: its footprint overlaps a median region whose opening attribute is true."}, {"name": "branch_2", "expected": "compliant", "narrative": "A car turning at an intersection of the divided highway clips the median nose: its footprint overlaps the median and the st.intersection region."}], "literals": [], "param_proposals": [], "gaps": []}
